    SongLuaOverlayUpdateTrack, SongLuaOverlayUpdateValue, SongLuaSpanMode,
    SongLuaStatefulMessageCapture, SongLuaTimeUnit, SongLuaTrackedActor, SongLuaTrackedActorTarget,
