fn preparation_actor_control(
    source: &str,
    context: &crate::SongLuaCompileContext,
    initialize: bool,
) -> mlua::Result<mlua::Lua> {
    let lua = legacy_actor_scene_with_setup("return Def.Actor{}", context, |lua| {
        legacy_constructor_before_frames(lua);
        install_legacy_file_loaders(lua, &context.song_dir)?;
        crate::install_basic_globals(lua, context, false)?;
        let game = crate::install_game_state_globals(lua, context)?;
        lua.set_app_data(game);
        lua.globals().set(
            "PREFSMAN",
            crate::create_prefsmgr_table(
                lua,
                context.global_offset_seconds,
                context.display_aspect_ratio,
                context.display_width.max(0.).round() as i32,
                context.display_height.max(0.).round() as i32,
                &context.video_renderers,
                &context.last_seen_video_driver,
                context.event_mode,
            )?,
        )?;
        let declaration = lua.load(source).set_name("@/fixture/actors.lua").eval()?;
        let root = construct_legacy_preparation_actor(lua, declaration)?;
        lua.globals().set("prepared_root", root.clone())?;
        // Startup reads screen options even in this isolated actor fixture.
        // The synthetic loader frame has no transition children or overrides.
        lua.globals().set("__songlua_top_screen", root.clone())?;
        if initialize {
            initialize_legacy_preparation_actor(lua, &root)?;
        }
        Ok(())
    })?;
    let root: mlua::Value = lua.globals().get("prepared_root")?;
    lua.globals().set("root", root)?;
    Ok(lua)
}

/// Run the actual compiler startup routine, including its global queue barrier,
/// zero update and discovery. The fixture root is the compiler's loader list.
pub fn start_legacy_preparation_actor_scene(
    lua: &mlua::Lua,
    context: &crate::SongLuaCompileContext,
) -> mlua::Result<()> {
    for key in crate::SONG_LUA_PLAYER_OPTIONS_KEYS
        .iter()
        .copied()
        .chain([crate::SONG_LUA_RUNTIME_KEY, "__songlua_top_screen"])
    {
        lua.globals()
            .get::<mlua::Table>(key)
            .map_err(|error| mlua::Error::external(format!("startup fixture {key}: {error}")))?;
    }
    let root = lua.globals().get("root")?;
    let mut initial = std::collections::HashMap::new();
    crate::lua_util::collect_initial_states(&root, &mut initial)?;
    crate::lua_util::run_actor_startup_commands(lua, &root, initial, context).map_err(|error| {
        let events = lua
            .load("return events and table.concat(events, '|') or ''")
            .eval::<String>()
            .unwrap_or_default();
        mlua::Error::external(format!("startup after [{events}]: {error}"))
    })?;
    Ok(())
}

pub fn legacy_actor_command_capture(
    lua: &mlua::Lua,
    actor: &mlua::Table,
) -> Result<super::ActorCommandCapture, String> {
    crate::lua_util::flush_actor_capture(actor).map_err(|e| e.to_string())?;
    let blocks = crate::lua_util::read_actor_capture_blocks(actor)?;
    let read = || -> mlua::Result<_> {
        let captured: mlua::Table = actor.get("__songlua_capture_blocks")?;
        let block_steps = captured
            .sequence_values::<mlua::Table>()
            .map(|block| {
                block?
                    .get::<Option<usize>>("__songlua_tween_step")
                    .map(|v| v.unwrap_or(0))
            })
            .collect::<mlua::Result<_>>()?;
        let steps = actor
            .get::<Option<mlua::Table>>("__songlua_command_queue_steps")?
            .map(|steps| {
                steps
                    .sequence_values::<mlua::Value>()
                    .map(|step| match step? {
                        mlua::Value::Boolean(false) => Ok(None),
                        value => Ok(Some(crate::read_f32(value).unwrap_or(0.))),
                    })
                    .collect::<mlua::Result<Vec<_>>>()
            })
            .transpose()?
            .unwrap_or_default();
        let starts = actor.get::<Option<mlua::Table>>("__songlua_command_queue_starts")?;
        let queued_commands = actor
            .get::<Option<mlua::Table>>("__songlua_command_queue")?
            .map(|queue| {
                queue
                    .sequence_values::<mlua::LuaString>()
                    .enumerate()
                    .map(|(i, name)| {
                        Ok((
                            name?.as_bytes().to_vec(),
                            starts
                                .as_ref()
                                .map(|starts| starts.raw_get::<Option<f32>>(i + 1))
                                .transpose()?
                                .flatten()
                                .unwrap_or(0.),
                        ))
                    })
                    .collect::<mlua::Result<Vec<_>>>()
            })
            .transpose()?
            .unwrap_or_default();
        Ok((block_steps, steps, queued_commands))
    };
    let (block_steps, steps, queued_commands) = read().map_err(|e| e.to_string())?;
    let _ = lua;
    Ok(super::ActorCommandCapture {
        blocks,
        block_steps,
        steps,
        queued_commands,
    })
}

