pub fn legacy_compile_static_schedule(
    lua: &mlua::Lua,
    paths: &[&std::path::Path],
    context: &crate::SongLuaCompileContext,
) -> Result<LegacyStaticSchedule, String> {
    lua.set_app_data(StaticScheduleProbe);
    lua.remove_app_data::<LegacyStaticSchedule>();
    let result = crate::compile::migration_compile_song_layers(lua, paths, 0, context);
    lua.remove_app_data::<StaticScheduleProbe>();
    if let Some(output) = lua.remove_app_data::<LegacyStaticSchedule>() {
        let error = result.expect_err("static schedule observer must stop the compiler");
        assert!(
            error.contains("migration static schedule boundary reached"),
            "{error}"
        );
        Ok(output)
    } else {
        Err(result
            .err()
            .unwrap_or_else(|| "static schedule boundary was not reached".into()))
    }
}

