    );
    assert!(
        captures
            .iter()
            .flat_map(|c| &c.writes)
            .all(|w| w.overlay_index == 1)
    );
}

#[test]
fn replay_message_provenance_keeps_tail_delays_hurry_and_queue_dispatch_resets() {
