            assert(__songlua_broadcast_messages.marker=='old-broadcasts' and __songlua_sound_calls.marker=='old-sounds')
            assert(__songlua_suppress_broadcast_dispatch=='old-suppress' and saved.a:GetX()==3 and saved.c:GetZ()==0)
            log(math.random())
        "#);
    }
}

