    let (_dir, mut pair) =
        command_scope_pair("return Def.Quad{InitCommand=function(self)saved.a=self;self:x(3)end}");
    pair.script(r#"
        local weak=setmetatable({}, {__mode='v'});saved.a.action_weak=weak
