            SongLuaTimeUnit::Beat,
            &names.1,
            |runtime, i, _| {
                let rows = runtime.capture_song_overlay_function_eases(
                    &[(0, Value::Table(b))],
                    i.function,
                    deadsync_song_lua::SongLuaOverlayEaseBuildParams {
                        unit: i.unit,
                        start: i.start,
                        limit: i.limit,
                        span_mode: i.span_mode,
                        easing: i.easing,
                        sustain: i.sustain,
                        opt1: i.opt1,
